package com.personalassistant.companion;

import android.app.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;

/** Sprints, session templates, the exercise picker, and one-day changes that leave the sprint plan as it is. */
final class WorkoutPlan {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;
    static final String[] PHASES={"Reconditioning","Hypertrophy","Strength","Aerobic base","Running","Alpine hiking","Lean bulk","Maintenance","Deload"};
    WorkoutPlan(WorkoutScreen s){screen=s;a=s.a;ui=s.ui;}

    void open(){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Sprints and templates");s.body.addView(ui.primaryButton("Plan a sprint",()->{s.dialog.dismiss();edit(null);}),WorkoutViews.gap(ui,12));s.body.addView(ui.label("Sprints"),WorkoutViews.gap(ui,6));List<JSONObject> sprints=WorkoutStore.rows(a,"sprint");Collections.sort(sprints,(x,y)->y.optJSONObject("data").optString("start").compareTo(x.optJSONObject("data").optString("start")));for(JSONObject r:sprints){JSONObject d=r.optJSONObject("data");s.body.addView(WorkoutViews.row(ui,d.optString("name"),d.optString("phase")+" · "+d.optString("start")+" to "+d.optString("end")+" · "+d.optString("status"),()->sprint(r.optString("id"))),WorkoutViews.gap(ui,8));}if(sprints.isEmpty())s.body.addView(ui.detail("No sprints yet."),WorkoutViews.gap(ui,8));
        s.body.addView(ui.label("Templates"),MainParts.params(ui,-1,-2,0,10,0,6));for(JSONObject r:templates())s.body.addView(WorkoutViews.row(ui,r.optJSONObject("data").optString("name"),screen.summary(r.optJSONObject("data")),()->template(r.optString("id"))),WorkoutViews.gap(ui,8));s.body.addView(ui.quietButton("New template",()->template(null)));s.show();}
    List<JSONObject> templates(){List<JSONObject> t=WorkoutStore.rows(a,"template");Collections.sort(t,(x,y)->x.optJSONObject("data").optString("name").compareTo(y.optJSONObject("data").optString("name")));return t;}

    /** Evidence, the coach's reading and the proposal stay separate; applying a next sprint happens in Coach, with approval. */
    void sprint(String id){JSONObject d=WorkoutStore.data(a,"sprint",id);if(d==null)return;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,d.optString("name"));s.body.addView(ui.detail(d.optString("phase")+" · "+d.optString("start")+" to "+d.optString("end")),WorkoutViews.gap(ui,10));JSONObject ev=null;JSONArray all=screen.overview().optJSONArray("sprints");for(int i=0;all!=null&&i<all.length();i++)if(id.equals(all.optJSONObject(i).optString("id")))ev=all.optJSONObject(i);LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("Evidence",15,20,700,0,ui.text));if(ev==null)c.addView(ui.type("Appears after your next sync.",13,18,400,0,ui.muted));else{c.addView(WorkoutViews.pair(ui,"Sessions",ev.optInt("completed")+" of "+ev.optInt("planned"),ui.text));if(ev.optInt("recovery_adjusted_skips")>0)c.addView(WorkoutViews.pair(ui,"Recovery skips, not counted",""+ev.optInt("recovery_adjusted_skips"),ui.text));if(!ev.isNull("average_duration_seconds")&&ev.has("average_duration_seconds"))c.addView(WorkoutViews.pair(ui,"Average session",WorkoutViews.clock(ev.optLong("average_duration_seconds")),ui.text));}s.body.addView(c,WorkoutViews.gap(ui,10));
        JSONArray goals=d.optJSONArray("success_criteria");if(goals!=null&&goals.length()>0){LinearLayout g=WorkoutViews.card(ui);g.addView(ui.type("Success criteria",15,20,700,0,ui.text));for(int i=0;i<goals.length();i++)g.addView(ui.type(goals.optString(i),13.5f,19,400,0,ui.text));s.body.addView(g,WorkoutViews.gap(ui,10));}
        JSONArray plan=d.optJSONArray("scheduled");LinearLayout p=WorkoutViews.card(ui);p.addView(ui.type("Plan",15,20,700,0,ui.text));for(int i=0;plan!=null&&i<plan.length();i++){JSONObject row=plan.optJSONObject(i);JSONObject t=WorkoutStore.data(a,"template",row.optString("template_id"));p.addView(WorkoutViews.pair(ui,LocalDate.parse(row.optString("date")).format(WorkoutScreen.SHORT),t==null?"Session":t.optString("name"),ui.muted));}s.body.addView(p,WorkoutViews.gap(ui,10));
        if(!d.optString("retrospective").isEmpty()){LinearLayout r=WorkoutViews.card(ui);r.addView(ui.type("Review",15,20,700,0,ui.text));r.addView(ui.type(d.optString("retrospective"),13.5f,19,400,0,ui.text));s.body.addView(r,WorkoutViews.gap(ui,10));}
        s.body.addView(ui.quietButton("Ask coach to review this sprint",()->{try{screen.coach.open(new JSONObject().put("purpose","sprint_review").put("sprint_id",id),null,"Review "+d.optString("name")+": evidence, your reading, and a proposed next sprint for my approval.");}catch(JSONException ignored){}}),WorkoutViews.gap(ui,8));s.body.addView(ui.quietButton("Edit sprint",()->{s.dialog.dismiss();edit(id);}),WorkoutViews.gap(ui,8));if("active".equals(d.optString("status")))s.body.addView(ui.ghostButton("Mark complete",()->{try{d.put("status","completed");WorkoutStore.put(a,"sprint",id,d);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}));s.show();}

    /** A sprint: phase, dates, goals, and which template falls on which weekdays. 14 days by default. */
    void edit(String id){JSONObject found=id==null?null:WorkoutStore.data(a,"sprint",id);JSONObject base;try{base=found==null?new JSONObject().put("status","active"):new JSONObject(found.toString());}catch(JSONException e){return;}final JSONObject d=base;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,id==null?"Plan a sprint":"Edit sprint");EditText name=ui.field("Name",d.optString("name","Sprint "+(WorkoutStore.rows(a,"sprint").size()+1)));s.body.addView(name,WorkoutViews.gap(ui,8));final String[] phase={d.optString("phase",PHASES[0])};Button pick=ui.quietButton("Focus: "+phase[0],null);pick.setOnClickListener(v->new AlertDialog.Builder(a).setItems(PHASES,(x,i)->{phase[0]=PHASES[i];pick.setText("Focus: "+phase[0]);}).show());s.body.addView(pick,WorkoutViews.gap(ui,8));LocalDate today=LocalDate.now();EditText start=ui.field("Start, YYYY-MM-DD",d.optString("start",today.toString())),days=ui.field("Length in days",d.has("start")?String.valueOf(LocalDate.parse(d.optString("start")).until(LocalDate.parse(d.optString("end"))).getDays()+1):"14");days.setInputType(InputType.TYPE_CLASS_NUMBER);s.body.addView(start,WorkoutViews.gap(ui,8));s.body.addView(days,WorkoutViews.gap(ui,8));EditText goals=ui.field("Success criteria, one per line",join(d.optJSONArray("success_criteria")));goals.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);goals.setSingleLine(false);goals.setMinLines(2);s.body.addView(goals,WorkoutViews.gap(ui,12));
        s.body.addView(ui.label("Weekly schedule"),WorkoutViews.gap(ui,6));List<JSONObject> t=templates();String[] names=new String[t.size()+1];names[0]="Rest";for(int i=0;i<t.size();i++)names[i+1]=t.get(i).optJSONObject("data").optString("name");final int[] chosen=new int[7];String[] weekdays={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};JSONArray plan=d.optJSONArray("scheduled");for(int i=0;plan!=null&&i<plan.length();i++){JSONObject row=plan.optJSONObject(i);int w=LocalDate.parse(row.optString("date")).getDayOfWeek().getValue()-1;for(int k=0;k<t.size();k++)if(t.get(k).optString("id").equals(row.optString("template_id")))chosen[w]=k+1;}for(int w=0;w<7;w++){final int day=w;Button b=ui.quietButton(weekdays[w]+": "+names[chosen[w]],null);b.setOnClickListener(v->new AlertDialog.Builder(a).setTitle(weekdays[day]).setItems(names,(x,i)->{chosen[day]=i;b.setText(weekdays[day]+": "+names[i]);}).show());s.body.addView(b,WorkoutViews.gap(ui,4));}if(t.isEmpty())s.body.addView(ui.detail("Create a template first, so a day has something to run."),WorkoutViews.gap(ui,8));
        s.body.addView(ui.primaryButton("Save sprint",()->{try{LocalDate first=LocalDate.parse(start.getText().toString().trim());int length=Integer.parseInt(days.getText().toString().trim());if(length<1)throw new IllegalArgumentException();LocalDate last=first.plusDays(length-1);JSONArray scheduled=new JSONArray();for(LocalDate x=first;!x.isAfter(last);x=x.plusDays(1)){int i=chosen[x.getDayOfWeek().getValue()-1];if(i>0)scheduled.put(new JSONObject().put("date",x.toString()).put("template_id",t.get(i-1).optString("id")));}JSONArray criteria=new JSONArray();for(String line:goals.getText().toString().split("\n"))if(!line.trim().isEmpty())criteria.put(line.trim());String title=name.getText().toString().trim();if(title.isEmpty())throw new IllegalArgumentException();d.put("name",title).put("phase",phase[0]).put("start",first.toString()).put("end",last.toString()).put("scheduled",scheduled).put("success_criteria",criteria);WorkoutStore.put(a,"sprint",id==null?WorkoutStore.id():id,d);s.dialog.dismiss();screen.refresh();}catch(Exception e){Toast.makeText(a,"Check the name, date and length",Toast.LENGTH_LONG).show();}}),MainParts.params(ui,-1,-2,0,10,0,0));s.show();}
    private static String join(JSONArray v){StringBuilder b=new StringBuilder();for(int i=0;v!=null&&i<v.length();i++)b.append(i==0?"":"\n").append(v.optString(i));return b.toString();}

    void template(String id){JSONObject found=id==null?null:WorkoutStore.data(a,"template",id);JSONObject d;try{d=found==null?new JSONObject().put("exercises",new JSONArray()):new JSONObject(found.toString());}catch(JSONException e){return;}WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,id==null?"New template":"Edit template");EditText name=ui.field("Name",d.optString("name"));s.body.addView(name,WorkoutViews.gap(ui,10));LinearLayout rows=ui.column();s.body.addView(rows);Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();JSONArray ex=d.optJSONArray("exercises");for(int i=0;i<ex.length();i++){final int index=i;JSONObject p=ex.optJSONObject(i);String detail=!p.isNull("distance_m")&&p.has("distance_m")?WorkoutViews.kg(p.optDouble("distance_m")/1000)+" km"+(p.has("speed_kmh")&&!p.isNull("speed_kmh")?" at "+WorkoutViews.kg(p.optDouble("speed_kmh"))+" km/h":""):p.optInt("sets",1)+" × "+p.optInt("min_reps")+"–"+p.optInt("max_reps")+(p.has("weight_kg")&&!p.isNull("weight_kg")?" · "+WorkoutViews.kg(p.optDouble("weight_kg"))+" kg":"")+(p.has("rir")&&!p.isNull("rir")?" · "+WorkoutViews.kg(p.optDouble("rir"))+" RIR":"");rows.addView(WorkoutViews.row(ui,WorkoutStore.exerciseName(a,p.optString("exercise_id")),detail,()->prescription(ex,index,paint[0])),WorkoutViews.gap(ui,8));}};paint[0].run();
        s.body.addView(ui.quietButton("Add exercise",()->pick(screen,e->{try{JSONObject p=new JSONObject().put("exercise_id",e).put("sets",1).put("min_reps",8).put("max_reps",12).put("rest_seconds",120);d.getJSONArray("exercises").put(p);prescription(d.getJSONArray("exercises"),d.getJSONArray("exercises").length()-1,paint[0]);paint[0].run();}catch(JSONException ignored){}})),WorkoutViews.gap(ui,8));
        s.body.addView(ui.primaryButton("Save template",()->{String title=name.getText().toString().trim();if(title.isEmpty()){name.setError("Enter a name");return;}try{d.put("name",title);WorkoutStore.put(a,"template",id==null?WorkoutStore.id():id,d);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}),WorkoutViews.gap(ui,8));if(id!=null)s.body.addView(ui.ghostButton("Delete template",()->{WorkoutStore.delete(a,"template",id);s.dialog.dismiss();screen.refresh();}));s.show();}
    private void prescription(JSONArray list,int index,Runnable after){JSONObject p=list.optJSONObject(index);boolean run=WorkoutStore.cardio(a,p.optString("exercise_id"));LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);String[][] fields=run?new String[][]{{"distance_m","Distance in metres"},{"speed_kmh","Speed in km/h"}}:new String[][]{{"sets","Sets"},{"min_reps","Reps from"},{"max_reps","Reps to"},{"weight_kg","Target kg"},{"rir","Reps in reserve"},{"rest_seconds","Rest in seconds"}};EditText[] inputs=new EditText[fields.length];for(int i=0;i<fields.length;i++){inputs[i]=ui.field(fields[i][1],p.has(fields[i][0])&&!p.isNull(fields[i][0])?WorkoutViews.kg(p.optDouble(fields[i][0])):"");inputs[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(inputs[i],WorkoutViews.gap(ui,6));}ScrollView sc=new ScrollView(a);sc.addView(box);new AlertDialog.Builder(a).setTitle(WorkoutStore.exerciseName(a,p.optString("exercise_id"))).setView(sc).setPositiveButton("Save",(x,i)->{try{for(int k=0;k<fields.length;k++){String v=inputs[k].getText().toString().trim().replace(',','.');String key=fields[k][0];if(v.isEmpty())p.remove(key);else if(key.equals("sets")||key.endsWith("reps")||key.equals("rest_seconds"))p.put(key,(int)Double.parseDouble(v));else p.put(key,Double.parseDouble(v));}if(p.optInt("max_reps")<p.optInt("min_reps"))p.put("max_reps",p.optInt("min_reps"));after.run();}catch(Exception e){Toast.makeText(a,"Check the numbers",Toast.LENGTH_SHORT).show();}}).setNeutralButton("Remove",(x,i)->{list.remove(index);after.run();}).setNegativeButton("Cancel",null).show();}
    /** After a session that differed: the template takes this session's exercises and set counts. Prescribed loads are kept. */
    void saveStructure(String id,JSONObject template,JSONArray used){new AlertDialog.Builder(a).setTitle("Update the template?").setMessage("Future sessions from this template will use today's exercises and set counts. Past sessions don't change.").setPositiveButton("Update template",(x,w)->{try{JSONObject t=new JSONObject(template.toString());JSONArray old=t.optJSONArray("exercises"),next=new JSONArray();for(int i=0;i<used.length();i++){JSONObject u=used.getJSONObject(i);JSONObject p=null;for(int k=0;old!=null&&k<old.length();k++)if(u.optString("eid").equals(old.getJSONObject(k).optString("exercise_id")))p=new JSONObject(old.getJSONObject(k).toString());if(p==null)p=new JSONObject().put("exercise_id",u.optString("eid")).put("min_reps",8).put("max_reps",12).put("rest_seconds",u.optInt("rest",120));p.put("sets",Math.max(1,u.getJSONArray("sets").length()));next.put(p);}t.put("exercises",next);WorkoutStore.put(a,"template",id,t);Toast.makeText(a,"Template updated",Toast.LENGTH_SHORT).show();}catch(JSONException ignored){}}).setNegativeButton("Keep template",null).show();}

    /** Search the catalog, or add a new exercise. */
    static void pick(WorkoutScreen screen,Consumer<String> chosen){AppUi ui=screen.ui;MainActivity a=screen.a;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Choose exercise");EditText search=ui.field("Search exercises","");search.setTag("exercise_search");s.body.addView(search,WorkoutViews.gap(ui,10));LinearLayout rows=ui.column();s.body.addView(rows);List<JSONObject> all=WorkoutStore.rows(a,"exercise");Collections.sort(all,(x,y)->x.optJSONObject("data").optString("name").compareToIgnoreCase(y.optJSONObject("data").optString("name")));Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);int n=0;for(JSONObject r:all){JSONObject d=r.optJSONObject("data");if(!q.isEmpty()&&!d.optString("name").toLowerCase(Locale.ROOT).contains(q))continue;if(++n>60)break;rows.addView(WorkoutViews.row(ui,d.optString("name"),d.optString("equipment"),()->{s.dialog.dismiss();chosen.accept(r.optString("id"));}),WorkoutViews.gap(ui,6));}};paint[0].run();search.addTextChangedListener(new TextWatcher(){public void afterTextChanged(Editable e){paint[0].run();}public void beforeTextChanged(CharSequence c,int x,int y,int z){}public void onTextChanged(CharSequence c,int x,int y,int z){}});
        s.body.addView(ui.quietButton("New exercise",()->{EditText name=ui.field("Exercise name",search.getText().toString().trim());Switch cardio=new Switch(a);cardio.setText("Timed distance, such as a run");LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);box.addView(name,WorkoutViews.gap(ui,8));box.addView(cardio);new AlertDialog.Builder(a).setTitle("New exercise").setView(box).setPositiveButton("Add",(x,i)->{String v=name.getText().toString().trim();if(v.isEmpty())return;try{String id=WorkoutStore.id();WorkoutStore.put(a,"exercise",id,new JSONObject().put("name",v).put("mode",cardio.isChecked()?"cardio":"strength"));s.dialog.dismiss();chosen.accept(id);}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}));s.show();}

    /** Today only: another sprint day, edited exercises, a shorter session, or rest. The sprint plan stays and the change goes to the review. */
    void change(JSONObject next){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Change today's workout");JSONObject sprint=next.optJSONObject("sprint");String sid=sprint.optString("id"),date=next.optString("date"),current=next.optString("template_id");JSONObject t=WorkoutStore.data(a,"template",current);String name=t==null?"Session":t.optString("name");s.body.addView(ui.label("Swap with another session"),WorkoutViews.gap(ui,6));HashSet<String> seen=new HashSet<>();JSONArray plan=sprint.optJSONObject("data").optJSONArray("scheduled");for(int i=0;plan!=null&&i<plan.length();i++){String tid=plan.optJSONObject(i).optString("template_id");if(tid.equals(current)||!seen.add(tid))continue;JSONObject other=WorkoutStore.data(a,"template",tid);if(other==null)continue;s.body.addView(WorkoutViews.row(ui,other.optString("name"),"Do this instead today",()->{s.dialog.dismiss();screen.begin(other.optString("name"),tid,sid,date,change("swap_day","Swapped "+name+" for "+other.optString("name"),date));}),WorkoutViews.gap(ui,8));}
        s.body.addView(ui.label("Or"),MainParts.params(ui,-1,-2,0,8,0,6));s.body.addView(WorkoutViews.row(ui,"Edit exercises for today","Starts the session; change anything as you go",()->{s.dialog.dismiss();screen.begin(name,current,sid,date,change("edit_exercises","Chose to edit today's exercises",date));}),WorkoutViews.gap(ui,8));s.body.addView(WorkoutViews.row(ui,"Shorter session","Keeps the first half of the exercises",()->{s.dialog.dismiss();screen.begin(name,current,sid,date,change("shorter","Shortened the session",date));JSONObject d=WorkoutStore.draft(a);if(d!=null&&screen.live!=null){JSONArray ex=d.optJSONArray("exercises");for(int i=ex.length()-1;i>=Math.max(1,(ex.length()+1)/2);i--)ex.remove(i);WorkoutStore.saveDraft(a,d);screen.live.d=d;screen.live.render();}}),WorkoutViews.gap(ui,8));s.body.addView(WorkoutViews.row(ui,"Rest today","Never counts as a miss",()->rest(s,name,current,sid,date)),WorkoutViews.gap(ui,10));s.body.addView(ui.detail("Changes apply to today only and are noted for your sprint review."));s.show();}
    private JSONObject change(String kind,String reason,String date){try{return new JSONObject().put("id",WorkoutStore.id()).put("at",OffsetDateTime.now().withNano(0).toString()).put("kind",kind).put("reason",reason).put("original_date",date);}catch(JSONException e){throw new IllegalStateException(e);}}
    private void rest(WorkoutViews.Sheet s,String name,String template,String sprint,String date){EditText why=ui.field("Why, such as still sore","");new AlertDialog.Builder(a).setTitle("Rest today?").setView(why).setPositiveButton("Rest",(x,i)->{try{String reason=why.getText().toString().trim();JSONObject w=new JSONObject().put("name",name).put("started_at",OffsetDateTime.now().withNano(0).toString()).put("timezone",ZoneId.systemDefault().getId()).put("status","skipped").put("recovery_adjusted",true).put("skip_reason",reason.isEmpty()?"Rest day":reason).put("sprint_id",sprint).put("template_id",template).put("session_changes",new JSONArray().put(change("rest_move",reason.isEmpty()?"Rest day":reason,date))).put("source",new JSONObject().put("companion",new JSONObject().put("scheduled_date",date)));WorkoutStore.put(a,"workout",WorkoutStore.id(),w);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}
}
